-- Biblioteca de itens e armas do Call of Cthulhu (lida por js/coc.js, igual aos catálogos da Ordem Paranormal).
-- Aplicar uma vez no SQL Editor do Supabase. Leitura pública, ninguém escreve pelo app.
-- Se esta tabela estiver vazia ou o Supabase falhar, o app usa a lista que já vem dentro do coc.js.
create table if not exists public.catalog_coc_items (
  id            text primary key check (char_length(id) between 1 and 120),
  category      text not null check (category in ('arm','mun','inv','fer','med','cam','ele','ent','rou','vei')),
  era           text not null check (era in ('2','m','b')),        -- '2' só anos 1920 · 'm' só moderna · 'b' as duas
  group_name    text,                                               -- grupo dentro da categoria (ex.: Pistolas, Rifles)
  name          text not null check (char_length(name) between 1 and 160),
  price_1920    text,
  price_modern  text,
  rare          boolean not null default false,
  weapon        jsonb,                                              -- só armas: {sk,d0,al0,dano,al,nat,mun,mal}
  sort_order    integer not null default 0,
  active        boolean not null default true,
  updated_at    timestamptz not null default now()
);
alter table public.catalog_coc_items enable row level security;
drop policy if exists "Anyone can read CoC items" on public.catalog_coc_items;
create policy "Anyone can read CoC items" on public.catalog_coc_items
  for select to anon, authenticated using (active);
revoke all on public.catalog_coc_items from anon, authenticated;
grant select on public.catalog_coc_items to anon, authenticated;

on conflict (id) do update set category=excluded.category, era=excluded.era, group_name=excluded.group_name, name=excluded.name,
  price_1920=excluded.price_1920, price_modern=excluded.price_modern, rare=excluded.rare, weapon=excluded.weapon, sort_order=excluded.sort_order, updated_at=now();
